"""Cross-platform native bundle with the appropriate bundled app icon."""
from pathlib import Path
import subprocess
import sys
root=Path(__file__).resolve().parent.parent
assets=root/'glassbalance'/'assets'
if sys.platform=='win32':
    icon=assets/'glassbalance_icon.ico'
elif sys.platform=='darwin':
    # Generated by scripts/build_macos.sh with sips/iconutil (no Pillow needed).
    icon=root/'build'/'glassbalance_icon.icns'
else:
    icon=assets/'glassbalance_icon.png'
if not icon.is_file():
    raise SystemExit(f'Missing icon: {icon}')
sep=';' if sys.platform=='win32' else ':'
args=[sys.executable,'-m','PyInstaller','--noconfirm','--clean','--windowed','--onedir','--name','GlassBalance',
      '--add-data',f'glassbalance/assets{sep}glassbalance/assets','--icon',str(icon)]
if sys.platform=='darwin':
    args+=['--osx-bundle-identifier','io.github.Onimee58.GlassBalance']
args.append('app.py')
subprocess.run(args,cwd=root,check=True)
